// WhatsApp click-to-chat: client reviews the message before opening WhatsApp.
(() => { const recipient = '919400243504'; const labels = { project_type: 'Project type', location: 'Project location', bathrooms: 'Number of bathrooms', area: 'Approximate area per bathroom', budget: 'Overall project budget', timeline: 'Preferred start', client_role: 'Client role', scope: 'Help required', renovation_needs: 'Renovation priorities', plumbing_changes: 'Plumbing / layout changes', makeover_needs: 'Makeover priorities', keep_layout: 'Existing layout', construction_stage: 'Construction stage', floor_plan: 'Floor plan availability', vision: 'Style, materials and other priorities', name: 'Client name', email: 'Email', phone: 'Phone / WhatsApp', contact_method: 'Preferred contact method', contact_time: 'Good time to contact' }; function message(data) { const lines = ['Hello The Bathstore, I would like to discuss my bathroom project.', '', '*CLIENT PROJECT ENQUIRY*', '']; for (const [key, label] of Object.entries(labels)) { const values = data.getAll(key).map(value => String(value).trim()).filter(Boolean); if (values.length) lines.push(label + ': ' + values.join(', ')) } return lines.join('\n') } function link(text) { return 'https://wa.me/' + recipient + '?text=' + encodeURIComponent(text) } window.BathstoreWhatsApp = { labels, message, link, recipient, displayRecipient: '+91 94002 43504' }; })();
